// Definition for a binary tree node.
class Node {
    int data;
    Node left;
    Node right;
    Node(int data) { this.data = data; }
}

public void postorder(Node root) {
    if (root == null) return;          // base case: nothing to visit
    postorder(root.left);              // 1) left subtree
    postorder(root.right);             // 2) right subtree
    System.out.print(root.data + " "); // 3) visit the node LAST
}

public void postorder(Node root) {
    if (root == null) return;
    Deque<Node> stack1 = new ArrayDeque<>();
    Deque<Node> stack2 = new ArrayDeque<>();
    stack1.push(root);
    while (!stack1.isEmpty()) {
        Node node = stack1.pop();
        stack2.push(node);                              // build Node-Right-Left on s2
        if (node.left != null) stack1.push(node.left);  // left first...
        if (node.right != null) stack1.push(node.right);// ...right popped first
    }
    while (!stack2.isEmpty()) {                         // drain reverses -> postorder
        System.out.print(stack2.pop().data + " ");
    }
}

