def postorder(root: Node) -> None:
    if root is None:
        return
    stack1 = [root]
    stack2 = []
    while stack1:
        node = stack1.pop()
        stack2.append(node)                 # build Node-Right-Left on stack2
        if node.left is not None:
            stack1.append(node.left)        # left first...
        if node.right is not None:
            stack1.append(node.right)       # ...right popped first
    while stack2:                           # drain reverses -> postorder
        print(stack2.pop().data, end=' ')

